def chain():
    actions = {0: ["go"], 1: ["go"], 2: []}
    next_state = {(0, "go"): 1, (1, "go"): 2}
    reward = {(0, "go"): 0.0, (1, "go"): 1.0}
    return actions, next_state, reward

def test_chain():
    actions, nxt, rew = chain()
    v = solution.value_iteration(3, actions, nxt, rew, 0.9)
    assert abs(v[0] - 0.9) < 1e-6
    assert abs(v[1] - 1.0) < 1e-6
    assert abs(v[2] - 0.0) < 1e-6

def test_best_action():
    actions = {0: ["short", "scenic"], 1: ["go"], 2: []}
    nxt = {(0, "short"): 1, (0, "scenic"): 2, (1, "go"): 2}
    rew = {(0, "short"): 0.0, (0, "scenic"): 0.5, (1, "go"): 1.0}
    v = solution.value_iteration(3, actions, nxt, rew, 0.9)
    assert abs(v[0] - 0.9) < 1e-6

def test_gamma_zero():
    actions, nxt, rew = chain()
    v = solution.value_iteration(3, actions, nxt, rew, 0.0)
    assert v == [0.0, 1.0, 0.0]

def test_terminal_state():
    actions = {0: []}
    v = solution.value_iteration(1, actions, {}, {}, 0.9)
    assert v == [0.0]

def test_invalid_gamma():
    actions, nxt, rew = chain()
    for bad in (-0.1, 1.5):
        try:
            solution.value_iteration(3, actions, nxt, rew, bad)
        except ValueError:
            continue
        raise AssertionError("expected ValueError")

def test_converges():
    actions, nxt, rew = chain()
    v = solution.value_iteration(3, actions, nxt, rew, 0.5, tol=1e-12)
    assert abs(v[0] - 0.5) < 1e-9
